drop policy if exists goal_versions_owner_access on public.goal_versions; create policy goal_versions_owner_select on public.goal_versions for select to authenticated using (exists(select 1 from public.goals g where g.id=goal_id and g.owner_user_id=(select auth.uid()))); create policy goal_versions_owner_insert on public.goal_versions for insert to authenticated with check (exists(select 1 from public.goals g where g.id=goal_id and g.owner_user_id=(select auth.uid()))); drop policy if exists goal_events_owner_access on public.goal_events; create policy goal_events_owner_select on public.goal_events for select to authenticated using (exists(select 1 from public.goals g where g.id=goal_id and g.owner_user_id=(select auth.uid()))); create policy goal_events_owner_insert on public.goal_events for insert to authenticated with check (exists(select 1 from public.goals g where g.id=goal_id and g.owner_user_id=(select auth.uid()))); revoke update,delete on public.goal_versions,public.goal_events from authenticated; grant select,insert on public.goal_versions,public.goal_events to authenticated;